INSERT INTO `chatbot_messages` VALUES (14,'sess_kzjs2z2yygotvbuuaeqr3',NULL,'user','Tìm các mẫu áo phông còn hàng','2026-06-08 03:08:25','2026-06-08 03:08:25'),(15,'sess_kzjs2z2yygotvbuuaeqr3',NULL,'assistant','Vion Era có một số mẫu áo phông đang còn hàng để bạn tham khảo đây ạ:\n\n**Áo Thun Nam Basic Oversize - Mã ID: 1**\n- Giá: 199,000đ\n- Size: S, M, L, XL\n- Màu sắc: Trắng, Đen, Xám\n- Tình trạng kho: Còn hàng đầy đủ các size và màu.\n- Gợi ý phối đồ: Mẫu áo này rất dễ phối với quần jean, quần short hoặc quần kaki để tạo phong cách năng động, thoải mái khi đi chơi, đi học.\n\n**Áo Thun Nam In Logo Vion Classic - Mã ID: 2**\n- Giá: 249,000đ\n- Size: M, L, XL\n- Màu sắc: Navy, Đen, Trắng\n- Tình trạng kho: Còn hàng đầy đủ các size và màu.\n- Gợi ý phối đồ: Áo thun in logo có thể kết hợp với quần jean hoặc quần âu để tạo vẻ ngoài lịch sự nhưng vẫn trẻ trung.\n\n**Áo Thun Nữ Crop Top Cotton - Mã ID: 10**\n- Giá: 179,000đ\n- Size: S, M, L\n- Màu sắc: Trắng, Đen, Hồng, Xanh mint\n- Tình trạng kho: Còn hàng đầy đủ các size và màu.\n- Gợi ý phối đồ: Áo crop top rất hợp với quần cạp cao, chân váy hoặc quần short để tôn dáng và tạo phong cách cá tính, thời thượng khi đi chơi hoặc dạo phố.\n\n**Đồ Bộ Trẻ Em Cotton Mềm Mại - Mã ID: 13**\n- Giá: 199,000đ (size 2T, 3T, 4T), 219,000đ (size 5T)\n- Size: 2T, 3T, 4T, 5T\n- Màu sắc: Xanh dương, Vàng\n- Tình trạng kho: Còn hàng đầy đủ các size và màu.\n- Gợi ý phối đồ: Bộ đồ này rất tiện lợi và thoải mái cho các bé mặc ở nhà, đi chơi hoặc đi học mẫu giáo.\n\nBạn quan tâm đến mẫu áo nào hay muốn mình tư vấn thêm về phong cách không?\n\n[PRODUCTS_JSON: [{\"id\": 1, \"name\": \"Áo Thun Nam Basic Oversize\", \"image\": \"https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616218/vion/products/a1rrgyopbsbn0jhiodra.jpg\", \"price\": 199000.0}, {\"id\": 2, \"name\": \"Áo Thun Nam In Logo Vion Classic\", \"image\": \"https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616223/vion/products/z9sb1xt3jdrlfdwmztcw.jpg\", \"price\": 249000.0}, {\"id\": 10, \"name\": \"Áo Thun Nữ Crop Top Cotton\", \"image\": \"https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616261/vion/products/gzbtzm9svzl8wbn9oyyh.jpg\", \"price\": 179000.0}, {\"id\": 13, \"name\": \"Đồ Bộ Trẻ Em Cotton Mềm Mại\", \"image\": \"https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616279/vion/products/tkwtpp1ra68s2owfuln6.jpg\", \"price\": 199000.0}]]','2026-06-08 03:08:43','2026-06-08 03:08:43'),(16,'sess_kzjs2z2yygotvbuuaeqr3',1,'user','Tìm các mẫu áo phông còn hàng','2026-06-11 07:33:45','2026-06-11 07:33:45'),(17,'sess_kzjs2z2yygotvbuuaeqr3',1,'assistant','Chào bạn, Vion Era có một số mẫu áo phông đang còn hàng đây ạ:\n\n**Áo Thun Nam Basic Oversize - Mã ID: 1**\n- Giá: 199,000đ\n- Size: S, M, L, XL\n- Màu sắc: Trắng, Đen, Xám\n- Tình trạng kho: Còn hàng đầy đủ các size và màu.\n- Gợi ý phối đồ: Mẫu áo này rất dễ phối đồ, bạn có thể mặc cùng quần jeans, quần short hoặc quần kaki để đi chơi, đi học đều rất thoải mái và năng động.\n\n**Áo Thun Nam In Logo Vion Classic - Mã ID: 2**\n- Giá: 249,000đ\n- Size: M, L, XL\n- Màu sắc: Navy, Đen, Trắng\n- Tình trạng kho: Còn hàng đầy đủ các size và màu.\n- Gợi ý phối đồ: Với thiết kế logo đơn giản, bạn có thể phối áo này với quần jeans hoặc quần âu để tạo phong cách trẻ trung, lịch sự khi đi làm hoặc đi chơi.\n\n**Áo Thun Nữ Crop Top Cotton - Mã ID: 10**\n- Giá: 179,000đ\n- Size: S, M, L\n- Màu sắc: Trắng, Đen, Hồng, Xanh mint\n- Tình trạng kho: Còn hàng đầy đủ các size và màu.\n- Gợi ý phối đồ: Áo crop top rất phù hợp để phối cùng quần cạp cao, chân váy hoặc quần short, giúp bạn tôn dáng và trông thật sành điệu khi đi dạo phố hay hẹn hò.\n\n**Đồ Bộ Trẻ Em Cotton Mềm Mại - Mã ID: 13**\n- Giá: 199,000đ (size 2T, 3T, 4T), 219,000đ (size 5T)\n- Size: 2T, 3T, 4T, 5T\n- Màu sắc: Xanh dương, Vàng\n- Tình trạng kho: Còn hàng đầy đủ các size và màu.\n- Gợi ý phối đồ: Bộ đồ này rất thích hợp cho các bé mặc ở nhà, đi chơi hoặc đi học mẫu giáo, vừa thoải mái lại vừa đáng yêu.\n\nBạn quan tâm đến mẫu nào hay muốn mình tư vấn thêm về phong cách nào không?\n\n[PRODUCTS_JSON: [{\"id\": 1, \"name\": \"Áo Thun Nam Basic Oversize\", \"image\": \"https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616218/vion/products/a1rrgyopbsbn0jhiodra.jpg\", \"price\": 199000.0}, {\"id\": 2, \"name\": \"Áo Thun Nam In Logo Vion Classic\", \"image\": \"https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616223/vion/products/z9sb1xt3jdrlfdwmztcw.jpg\", \"price\": 249000.0}, {\"id\": 10, \"name\": \"Áo Thun Nữ Crop Top Cotton\", \"image\": \"https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616261/vion/products/gzbtzm9svzl8wbn9oyyh.jpg\", \"price\": 179000.0}, {\"id\": 13, \"name\": \"Đồ Bộ Trẻ Em Cotton Mềm Mại\", \"image\": \"https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616279/vion/products/tkwtpp1ra68s2owfuln6.jpg\", \"price\": 199000.0}]]','2026-06-11 07:33:53','2026-06-11 07:33:53');
