INSERT INTO `products` VALUES (1,5,'Áo Thun Nam Basic Oversize','https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616218/vion/products/a1rrgyopbsbn0jhiodra.jpg','Áo thun nam oversize form rộng thoải mái, chất cotton 100% thoáng mát, phù hợp mặc đi chơi, đi học.','Cotton 100%','Giặt máy ở nhiệt độ thường, không dùng thuốc tẩy, phơi trong bóng mát.',0,'2026-05-24 02:50:17','2026-05-24 02:50:17'),(2,5,'Áo Thun Nam In Logo Vion Classic','https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616223/vion/products/z9sb1xt3jdrlfdwmztcw.jpg','Áo thun in logo thương hiệu Vion phía trước, chất liệu cotton mềm mại, giữ form lâu.','Cotton 95%, Spandex 5%','Giặt lộn mặt trong, nhiệt độ ≤30°C.',2,'2026-05-24 02:50:22','2026-06-08 07:53:15'),(3,6,'Quần Jeans Nam Slim Fit Co Giãn','https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616228/vion/products/y1z0zmyr6dvyxhs5jrxh.jpg','Quần jeans nam slim fit, chất vải denim co giãn 4 chiều, tôn dáng, dễ phối đồ.','Denim 98%, Spandex 2%','Giặt lộn mặt trong, nhiệt độ ≤30°C, không vắt mạnh.',0,'2026-05-24 02:50:27','2026-05-24 02:50:27'),(4,1,'Quần Short Nam Kaki Linen','https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616234/vion/products/lfeepzahljqdhqlpo9mc.jpg','Quần short nam chất liệu linen mát mẻ, thoáng khí, phù hợp mùa hè.','Linen 55%, Cotton 45%','Giặt tay nhẹ nhàng hoặc giặt máy chế độ nhẹ.',0,'2026-05-24 02:50:33','2026-05-24 02:50:33'),(5,4,'Áo Polo Vion Pique Classic','https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616239/vion/products/gdjshmepvfomh4mpkflp.jpg','Áo polo nam thêu logo Vion tinh tế, chất pique cao cấp, form regular fit lịch sự.','Pique Cotton 100%','Giặt máy ≤40°C, là ủi ở nhiệt độ thấp.',0,'2026-05-24 02:50:38','2026-05-24 02:50:38'),(6,1,'Áo Sơ Mi Nam Dài Tay Oxford','https://res.cloudinary.com/dlbx0uxqd/image/upload/v1779616244/vion/products/gqdgjur7jnsde0pyizf4.jpg','Áo sơ mi nam dài tay chất vải Oxford bền đẹp, form slim fit, phù hợp đi làm và đi chơi.','Oxford Cotton 100%','Là ủi ở